import type { ReactNode } from "react";

/**
 * Shared "app window" chrome for the marketing showcase mock-screens — the same
 * visual language as the terminal/browser mocks on the vibe-coding page: a dark
 * navy panel, macOS traffic lights, a small title, and an optional right-hand
 * status pill. All showcase screens compose their body inside this frame so the
 * set reads as one designed system.
 *
 * Server-safe (no client JS). Motion lives inside the body via `motion-safe:`
 * utilities, and the whole frame is meant to be wrapped in <Reveal> at the call
 * site for the scroll fade-in.
 */
export function ScreenFrame({
  title,
  icon,
  live,
  liveLabel = "live",
  children,
  className = "",
}: {
  title: string;
  icon?: ReactNode;
  /** Show a pulsing green status pill in the header. */
  live?: boolean;
  liveLabel?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <div
      className={`relative overflow-hidden rounded-2xl border border-white/10 bg-[#0a0e1a] shadow-2xl shadow-black/40 ${className}`}
    >
      {/* soft brand aura behind the panel edges */}
      <div
        className="pointer-events-none absolute -inset-10 -z-10 opacity-70"
        style={{
          backgroundImage:
            "radial-gradient(ellipse 50% 55% at 12% 0%, rgba(59,130,246,0.16), transparent), radial-gradient(ellipse 45% 55% at 90% 100%, rgba(138,112,251,0.18), transparent)",
        }}
        aria-hidden
      />
      <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.03] px-4 py-2.5">
        <span className="h-3 w-3 rounded-full bg-[#ff5f57]" />
        <span className="h-3 w-3 rounded-full bg-[#febc2e]" />
        <span className="h-3 w-3 rounded-full bg-[#28c840]" />
        <span className="ml-2 flex min-w-0 items-center gap-1.5 text-[11px] font-medium text-slate-400">
          {icon && <span className="text-slate-500">{icon}</span>}
          <span className="truncate">{title}</span>
        </span>
        {live && (
          <span className="ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
            {liveLabel}
          </span>
        )}
      </div>
      <div className="relative">{children}</div>
    </div>
  );
}

/** A thin animated usage/progress bar that fills on load (grows from the left). */
export function UsageBar({
  pct,
  from = "var(--color-accent-blue)",
  to = "var(--color-brand-500)",
  delay = 0,
  className = "",
}: {
  pct: number;
  from?: string;
  to?: string;
  delay?: number;
  className?: string;
}) {
  return (
    <div className={`h-2 w-full overflow-hidden rounded-full bg-white/[0.06] ${className}`}>
      <div
        className="h-full origin-left rounded-full motion-safe:animate-grow-x"
        style={{
          width: `${pct}%`,
          backgroundImage: `linear-gradient(90deg, ${from}, ${to})`,
          animationDelay: `${delay}ms`,
        }}
      />
    </div>
  );
}

import { ScreenFrame, UsageBar } from "./Frame";
